INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-desafio-del-silencio-comunicativo', 'El Desafío del Silencio Comunicativo', 'Dinámica de expresión gestual y cooperación no verbal donde los scouts transmiten mensajes complejos sin emitir sonido alguno.', '<h2>📜 Descripción de El Desafío del Silencio Comunicativo</h2>
<p><b>El Desafío del Silencio Comunicativo</b> es una dinámica scout enfocada en el desarrollo de la empatía, el lenguaje corporal y la agilidad de interpretación colectiva. En esta actividad, los participantes deben organizarse, resolver acertijos o transmitir consignas secretas de campamento utilizando únicamente gestos, mímica y contacto visual, quedando estrictamente prohibido el uso de la voz o de la escritura. La patrulla aprende a sincronizar sus códigos no verbales para resolver desafíos de ordenamiento, secuencias históricas o armado de estructuras simples en un entorno de concentración y diversión.</p>
<p>Esta dinámica potencia la observación fina, la paciencia y la inclusión de todos los beneficiarios en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Desafío del Silencio Comunicativo?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y dinamismo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Voto de Silencio Scout:</b> El dirigente reúne a la unidad en círculo e introduce la consigna del silencio absoluto. Cada patrulla se alinea hombro con hombro.</li>
  <li><b>Entrega de la Misión Secreta:</b> El animador muestra de forma confidencial al primer integrante de cada fila una tarjeta con una consigna (ej. <i>''Ordenar la patrulla por fecha de cumpleaños de enero a diciembre''</i> o <i>''Representar la construcción de un altar de campamento''</i>).</li>
  <li><b>Transmisión Gestual:</b> El primer scout transmite la instrucción a su compañero contiguo utilizando solo mímica, señas corporales y miradas.</li>
  <li><b>Ejecución Colectiva:</b> Una vez comprendido el mensaje, la patrulla ejecuta la acción en equipo manteniendo el silencio absoluto hasta completar la prueba.</li>
  <li><b>Evaluación y Reflexión:</b> Se rompe el silencio para verificar la exactitud de la misión realizada y compartir los aprendizajes del lenguaje no verbal.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Desafío del Silencio Comunicativo</h2>
<p>La actividad valora la precisión interpretativa y el autocontrol en el Tally:</p>
<ul>
  <li><b>Mayor Exactitud No Verbal:</b> Otorgar 5 puntos a la patrulla o seisena que interprete la consigna con la máxima fidelidad sin romper el silencio.</li>
  <li><b>Mejor Autocontrol:</b> Otorgar 3 puntos a la unidad que mantenga la concentración y el silencio durante toda la prueba.</li>
  <li><b>Espíritu de Inclusión:</b> Otorgar 3 puntos al grupo que integre a todos sus miembros activamente en la representación gestual.</li>
</ul>', '/uploads/el-desafio-del-silencio-comunicativo.webp', 'publicado', '{"areas": ["sociabilidad", "creatividad", "afectividad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Tarjetas de Misiones"], "objetivos": ["Fomentar la comunicación e interpretación", "Estimular la agilidad mental", "Trabajo en equipo", "Fomentar un entorno de confianza"], "justificacion_areas": "El Desafío del Silencio Comunicativo potencia la sociabilidad al enseñar a los beneficiarios a escucharse visualmente y respetar los tiempos de sus compañeros. Desarrolla la creatividad al requerir soluciones ingeniosas de expresión corporal frente a misiones complejas. Fortalece la afectividad al afianzar la empatía no verbal y la paciencia dentro del equipo.", "variaciones": "<b>Silencio a Oscuras:</b> Realizar las señas con linternas de colores en una noche de campamento.<br><b>Cadena de Nudos Silenciosa:</b> Transmitir las instrucciones para realizar un nudo scout específico usando únicamente mímica de manos.<br><b>Silencio en la Selva:</b> Adaptar el marco simbólico de Manada donde los lobatos se comunican en clave secreta para no ser descubiertos por Shere Khan.", "recomendaciones": "Mantener un tono positivo y festivo. Evitar sancionar errores con dureza; en su lugar, reforzar el esfuerzo de comunicación de cada participante.", "objetivos_educativos": [{"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Acatando con lealtad la regla de no hablar durante el desarrollo de la prueba."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Respetando los turnos de expresión no verbal de mis compañeros de seisena."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando el respeto y la atención dedicada hacia las señas de las demás personas."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo un ambiente de integración, escucha atenta y lealtad de patrulla."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Cumpliendo las consignas del silencio scout con responsabilidad compartida."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y hermandad comunitaria en toda la Tropa."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

